        self.shop(catalog="# c\n\nAB-100|x|12.505|1\n")
        err = self.fails(1, "stock")
        self.assertEqual(err, "stockroom: catalog.txt: line 3: bad price '12.505'\n")

    def test_movement_error_names_movements(self):
        self.shop(movements="2024-03-01 AB-100 -1\n")
        self.assertIn("stockroom: movements.txt: line 1:", self.fails(1, "stock"))

    def test_missing_catalog_is_exit_2_for_every_command(self):
        self.shop(catalog=None)
        for args in (("stock",), ("low",), ("history", "AB-100"), ("quote", "SO-1"), ("report",),
        self.shop()
        self.assertIn("SO-9", self.fails(1, "quote", "SO-9"))
        self.fails(1, "quote", "SO-1")  # SO-1 and SO-1001 differ
        self.fails(1, "quote", "whatever")

    def test_leading_zero_orders_are_distinct(self):
        self.shop(orders="SO-7 2024-01-01 a AB-100*1\nSO-007 2024-01-01 b AB-100*2\n")
        self.assertTrue(self.ok("quote", "SO-007").startswith("SO-007 2024-01-01 b\n"))
        self.assertTrue(self.ok("quote", "so-7").startswith("SO-7 2024-01-01 a\n"))

    def test_error_in_orders_names_file_and_line(self):
        self.shop(orders="\nSO-1 2024-01-01 a ZZ-999*1\n")
        self.assertEqual(self.fails(1, "quote", "SO-1"),
                         "stockroom: orders.txt: line 2: unknown SKU 'ZZ-999'\n")


